// Mark Overrun: runs when the AI calls mark_overrun, the moment the slime takes a whole block.
// It switches on that block's report in Block Reports, so the lore the narrator reads tells the block as fallen.

// 1. Find the block's report. args.block is one of the blocks this Tool lists, and each one has a report
//    named after it in the Block Reports lorebook.
const blockName = String(args.block);
const reportName = blockName + " Overrun";

// 2. A block falls once. A second call for the same block changes nothing, and the reply tells the AI so.
if (dictionaries["Block Reports"].entries[reportName].enabled) {
  return blockName + " is already overrun. Write the narration.";
}

// 3. Switch the report on, and log the fall in the Memory panel with the rest of the night.
dictionaries["Block Reports"].entries[reportName].enabled = true;
memories.add(blockName + " fell to the slime.");
return blockName + " is marked overrun. Write the narration.";
